pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerChoice) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        Reverter reverter = new Reverter();

        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        vm.prank(address(reverter));
        try c.withdrawAll() {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore - depositAmount);
        } catch {
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("ETH transfer failed");
    }
}
